function toggleDetachedConsole(){if(detachedWindow&&!detachedWindow.closed)attachConsole();else detachConsole()}
function fitDetachedConsole(){
    const popup=detachedWindow;
    if(!popup||popup.closed)return;
    const resize=()=>{if(detachedWindow===popup&&!popup.closed){sizeTerminal();term?.focus()}};
    popup.requestAnimationFrame(()=>popup.requestAnimationFrame(resize));
    for(const delay of [60,180,400])popup.setTimeout(resize,delay);
}
function detachConsole(){
    ensureTerm();
    const panel=document.getElementById('console');
    if(!panel||panel.classList.contains('console-detached-placeholder'))return;
    const popup=window.open('','saslik-cli','popup,width=1050,height=720');
    if(!popup){toast('Browser zablokoval nové okno');return}
    detachedWindow=popup;
    consolePanelHome={parent:panel.parentNode,next:panel.nextSibling};
    consolePlaceholder=document.createElement('section');
    consolePlaceholder.id='console';
    consolePlaceholder.className=`${panel.className} console-detached-placeholder`;
    consolePlaceholder.innerHTML='<div><b>Konzole běží v samostatném okně</b><span>Historie i aktivní CLI relace zůstávají tam.</span><button id="cli-attach-here">Připojit sem</button><small>nebo stiskni Enter</small></div>';
    panel.replaceWith(consolePlaceholder);
    consolePlaceholder.querySelector('button').onclick=attachConsole;
    popup.document.open();
    popup.document.write(`<!doctype html><html lang="cs"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Saslik · Smithproxy CLI</title><link rel="stylesheet" href="${location.origin}${location.pathname.replace(/[^/]*$/,'')}xterm.css"><link rel="stylesheet" href="${location.origin}${location.pathname.replace(/[^/]*$/,'')}style.css"></head><body class="console-only compact"><main id="detached-console-root"></main></body></html>`);
    popup.document.close();
    popup.document.getElementById('detached-console-root').appendChild(panel);
    panel.classList.remove('hidden');
    $('cli-detach').textContent='Vrátit do karty ↙';
    popup.onbeforeunload=()=>attachConsole(false);
    popup.onresize=fitDetachedConsole;
    popup.addEventListener('load',fitDetachedConsole,{once:true});
    detachedResizeObserver=new popup.ResizeObserver(fitDetachedConsole);
    detachedResizeObserver.observe(popup.document.getElementById('detached-console-root'));
    popup.focus();
    fitDetachedConsole();
}
function attachConsole(closePopup=true){
    if(!detachedWindow)return;
    const popup=detachedWindow,panel=popup.closed?null:popup.document.getElementById('console');
    detachedResizeObserver?.disconnect();
    detachedResizeObserver=null;
    detachedWindow=null;
    if(popup&&!popup.closed)popup.onbeforeunload=null;
    if(panel&&consolePlaceholder){
        consolePlaceholder.replaceWith(panel);
        panel.classList.toggle('hidden',activeTab!=='console');
        const detach=panel.querySelector('#cli-detach');
        if(detach)detach.textContent='Do okna ↗';
    }
    consolePlaceholder=null;
    consolePanelHome=null;
    if(closePopup&&popup&&!popup.closed)popup.close();
    requestAnimationFrame(()=>{fit?.fit();term?.focus()});
}

const renderHealthWithExplicitProxies=renderHealth;
renderHealth=function(health){
    renderHealthWithExplicitProxies(health);
    const check=health.checks?.socks||{state:'unknown',detail:'zatím neměřeno'};
    const node=document.createElement('article');
    node.className=`health state-${esc(check.state)}`;
    node.innerHTML=`<div><i></i><strong>SOCKS5</strong></div><small>TCP/1080 listener</small><b>${esc(check.detail||'—')}</b><span>${check.latency_ms==null?'—':`${check.latency_ms} ms`}</span>`;
    $('health-checks').appendChild(node);
    renderListenerStats(health.listener_stats||{});
    renderSiftStats(health.sift_stats||{});
};

function renderListenerStats(value){
    const listeners=Array.isArray(value.listeners)?value.listeners.filter(item=>item&&item.workers>0):[];
    $('listener-stats').innerHTML=listeners.length?listeners.map(item=>`<article class="runtime-stat"><small>${esc(item.name||'vstup proxy')}</small><strong>${Number(item.sessions_active||0).toLocaleString()} aktivních</strong><b>${Number(item.sessions_total||0).toLocaleString()} spojení celkem</b><span>do proxy ${humanBytes(Number(item.bytes_up||0))} · z proxy ${humanBytes(Number(item.bytes_down||0))}</span></article>`).join(''):'<span class="muted">Statistiky provozu přes proxy zatím nejsou dostupné.</span>';
}

function renderSiftStats(value){
    const engine=value.engine||{},flows=engine.flows||{},traffic=engine.traffic||{},http=value.http||{},timing=engine.timing?.total_delay_us||{};
    if(!value.service){$('sift-stats').innerHTML='<span class="muted">Sift diagnostika zatím není dostupná.</span>';return}
    const failed=Number(http.responses_4xx||0)+Number(http.responses_5xx||0);
    const cards=[['Flow lifecycle',`${Number(flows.active||0).toLocaleString()} aktivních`,`${Number(flows.seen||0).toLocaleString()} seen · peak ${Number(flows.peak||0).toLocaleString()}`],['Payloady',humanBytes(Number(traffic.bytes||0)),`${Number(traffic.payloads||0).toLocaleString()} zpráv`],['HTTP transport',`${Number(http.responses_2xx||0).toLocaleString()} OK`,`${failed.toLocaleString()} chyb · last ${Number(http.last_status||0)||'—'}`],['Klasifikace',`${Number(engine.signatures?.matches||0).toLocaleString()} matchů`,`${Number(timing.samples||0).toLocaleString()} vzorků · median ${Number(timing.median||0).toFixed(1)} µs`]];
    $('sift-stats').innerHTML=cards.map(([name,valueText,detail])=>`<article class="runtime-stat"><small>${esc(name)}</small><strong>${esc(valueText)}</strong><span>${esc(detail)}</span></article>`).join('');
}

const renderEndToEndWithExplicitProxies=renderEndToEnd;
renderEndToEnd=function(value){
    renderEndToEndWithExplicitProxies(value);
    const labels={http_connect:['HTTP CONNECT','explicit proxy · HTTPS'],socks:['SOCKS5','explicit proxy · remote DNS']};
    for(const [key,[label,kind]] of Object.entries(labels)){
        const check=value.checks?.[key]||{state:'unknown',detail:'čeká na první měření'};
        const state=value.stale?'degraded':check.state;
        const node=document.createElement('article');
        node.className=`e2e state-${esc(state||'unknown')}`;
        node.innerHTML=`<div><i></i><strong>${label}</strong></div><small>${kind}</small><b title="${esc(check.detail||'—')}">${esc(check.detail||'—')}</b><span>${check.latency_ms==null?'—':`${check.latency_ms} ms`}</span>`;
        $('e2e-checks').appendChild(node);
    }
};

const renderTrafficFlowWithExplicitProxies=renderTrafficFlow;
renderTrafficFlow=function(value){
    renderTrafficFlowWithExplicitProxies(value);
    const target=value.target||'example.com',checks=value.checks||{},list=document.querySelector('#traffic-flow-body .flow-list');
    const add=(key,label,entry,protocol,success)=>{
        const check=checks[key]||{},state=value.stale?'degraded':check.state||'unknown';
        const result=check.state==='ok'?success:check.detail||'čeká';
        const path=['probe/eth0 · 10.254.78.2',entry,protocol,'Smithproxy','sxp-test/eth0 · 10.254.77.2','sxp-test0 · SNAT',`${target}:443`];
        list?.insertAdjacentHTML('beforeend',`<article class="flow-row"><strong>${label}</strong><code>${path.map(part=>`<span>${esc(part)}</span>`).join('<i>→</i>')}</code><span class="flow-result state-${esc(state)}"><i></i><b>${esc(result)}</b>${check.latency_ms==null?'':`<small>${check.latency_ms} ms</small>`}</span></article>`);
    };
    add('http_connect','CONNECT','10.254.78.1:33128','HTTP CONNECT','CONNECT OK');
    add('socks','SOCKS5','10.254.78.1:1080','SOCKS5 + remote DNS','SOCKS OK');
};

